package com.akshay.stockflow.procurement;
import com.akshay.stockflow.product.*; import com.akshay.stockflow.supplier.*; import jakarta.transaction.Transactional; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/purchase-orders") public class PurchaseOrderController {
private final PurchaseOrderRepository orders; private final SupplierRepository suppliers; private final ProductRepository products;
public PurchaseOrderController(PurchaseOrderRepository orders,SupplierRepository suppliers,ProductRepository products){this.orders=orders;this.suppliers=suppliers;this.products=products;}
@GetMapping public List<PurchaseOrder> all(){return orders.findAll();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public PurchaseOrder create(@Valid @RequestBody OrderInput input){Supplier supplier=suppliers.findById(input.supplierId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Supplier not found"));if(!supplier.isActive())throw new ResponseStatusException(HttpStatus.CONFLICT,"Supplier is inactive");List<PurchaseOrderLine> lines=input.lines().stream().map(line->{Product p=products.findById(line.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found: "+line.productId()));return new PurchaseOrderLine(p.getId(),p.getSku(),p.getName(),line.quantity(),line.unitCost());}).toList();return orders.save(new PurchaseOrder(supplier.getId(),supplier.getName(),lines));}
@PostMapping("/{id}/receive") @Transactional public PurchaseOrder receive(@PathVariable Long id){PurchaseOrder order=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Purchase order not found"));if(order.getStatus()==PurchaseOrder.Status.RECEIVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Purchase order has already been received");for(PurchaseOrderLine line:order.getLines()){Product p=products.findById(line.getProductId()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Product no longer exists: "+line.getSku()));p.setQuantity(p.getQuantity()+line.getQuantity());products.save(p);}order.setStatus(PurchaseOrder.Status.RECEIVED);return orders.save(order);}
public record OrderInput(@NotNull Long supplierId,@NotEmpty List<@Valid LineInput> lines){} public record LineInput(@NotNull Long productId,@Min(1) @Max(1000000) int quantity,@DecimalMin("0.0") double unitCost){}
}
